import { defineConfig } from "vite-plus";

const ignorePatterns = [
  // Generated by @tanstack/router-plugin. Committed so type checks work before a build.
  "**/routeTree.gen.ts",
  // Agent skills installed from upstream (tracked by skills-lock.json). Must stay byte-identical.
  ".agents/**",
  // Symlinks to .agents/skills. The rest of .kiro/ (hooks, settings, steering) is checked like any other file.
  ".kiro/skills/**",
];

const runtimeImportMessage =
  "Runtime-specific code belongs in an entry file such as apps/api/src/server.ts (docs/adr/0007).";

const childProcessMessage =
  "Start git and other processes through gitIn() or runIn() from tools/scripts/src/test/sandbox.ts, which refuse " +
  'to act outside the sandbox (docs/tooling/ci.md ("スクリプトのテスト")).';

// Rules of typescript-eslint's `recommended-type-checked` that Oxlint does not enable by default, plus three
// stricter ones (docs/adr/0020). They stop `any`, `!`, narrowing `as` and @ts-ignore, the ways to silence a
// type error. A description is required after @ts-expect-error.
const typedRules: Record<string, "error" | ["error", ...unknown[]]> = {
  "typescript/ban-ts-comment": ["error", { "ts-expect-error": "allow-with-description" }],
  "typescript/no-explicit-any": "error",
  "typescript/no-empty-object-type": "error",
  "typescript/no-namespace": "error",
  "typescript/no-require-imports": "error",
  "typescript/no-unnecessary-type-constraint": "error",
  "typescript/no-unsafe-function-type": "error",
  "typescript/no-misused-promises": "error",
  "typescript/no-unnecessary-type-assertion": "error",
  "typescript/no-unsafe-argument": "error",
  "typescript/no-unsafe-assignment": "error",
  "typescript/no-unsafe-call": "error",
  "typescript/no-unsafe-member-access": "error",
  "typescript/no-unsafe-return": "error",
  "typescript/no-unsafe-enum-comparison": "error",
  "typescript/only-throw-error": "error",
  "typescript/prefer-promise-reject-errors": "error",
  "typescript/require-await": "error",
  "typescript/restrict-plus-operands": "error",
  // Stricter than recommended-type-checked.
  "typescript/switch-exhaustiveness-check": "error",
  "typescript/no-non-null-assertion": "error",
  "typescript/no-unsafe-type-assertion": "error",
};

// Root config for `vp check` / `vp lint` / `vp fmt`.
// Task orchestration and caching are handled by Nx, not `vp run` (see docs/adr/0002).
export default defineConfig({
  fmt: {
    ignorePatterns,
  },
  lint: {
    ignorePatterns,
    jsPlugins: [{ name: "vite-plus", specifier: "vite-plus/oxlint-plugin" }],
    rules: {
      "vite-plus/prefer-vite-plus-imports": "error",
      ...typedRules,
    },
    options: {
      typeAware: true,
      typeCheck: true,
      // A warning fails `vp check` too. Without this a warning-level rule such as no-floating-promises
      // passes CI (docs/adr/0020).
      denyWarnings: true,
      reportUnusedDisableDirectives: "error",
    },
    overrides: [
      // Agent-written tests: block .only (runs a subset) and .skip (hides a failing test).
      // See docs/code-review/agent-pull-requests.md.
      {
        files: ["**/*.test.ts", "**/*.test.tsx"],
        plugins: ["vitest"],
        rules: { "vitest/no-focused-tests": "error", "vitest/no-disabled-tests": "error" },
      },
      // ADR 0007: apps/api/src uses Web standard APIs only, so the app runs on Node.js,
      // Lambda and Cloudflare Workers. Runtime-specific code lives in the entry files below.
      {
        files: ["apps/api/src/**"],
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "error",
          "no-restricted-imports": [
            "error",
            {
              paths: [
                { name: "bun", message: runtimeImportMessage },
                { name: "@hono/node-server", message: runtimeImportMessage },
                { name: "@hono/aws-lambda", message: runtimeImportMessage },
                { name: "@hono/node-ws", message: runtimeImportMessage },
              ],
              patterns: [{ group: ["bun:*"], message: runtimeImportMessage }],
            },
          ],
          "no-restricted-globals": [
            "error",
            { name: "process", message: "Read environment variables from `c.env`." },
            { name: "Bun", message: runtimeImportMessage },
            { name: "Buffer", message: "Use Uint8Array, TextEncoder or TextDecoder." },
            { name: "__dirname", message: "Use `import.meta.url`." },
            { name: "__filename", message: "Use `import.meta.url`." },
            { name: "require", message: "Use `import`." },
          ],
        },
      },
      // Runtime-specific entry files and tests. Add new entry files (Lambda, Workers, ...) here.
      {
        files: ["apps/api/src/server.ts", "apps/api/src/**/*.test.ts"],
        // A plugin rule can only be turned off in an override that also lists the plugin.
        plugins: ["import"],
        rules: {
          "import/no-nodejs-modules": "off",
          "no-restricted-imports": "off",
          "no-restricted-globals": "off",
        },
      },
      // Tests of tools/scripts run from Git hooks, where a git command can act on this repository instead of
      // the temporary one (docs/tooling/ci.md ("スクリプトのテスト")). They start processes only through the
      // helpers in tools/scripts/src/test/, which are not test files. Dynamic import() and createRequire are
      // outside this rule; tools/scripts/src/test/isolation.test.ts catches what they would do.
      {
        files: ["tools/scripts/src/**/*.test.ts"],
        rules: {
          "no-restricted-imports": [
            "error",
            {
              paths: [
                { name: "node:child_process", message: childProcessMessage },
                { name: "child_process", message: childProcessMessage },
              ],
            },
          ],
        },
      },
      // The frontend logs nothing to the browser console (docs/logging/frontend.md).
      // Collect client errors with an error tracking service instead.
      {
        files: ["apps/web/src/**"],
        rules: { "no-console": "error" },
      },
      // Code that opens an XSS hole (docs/web-frontend/static-analysis.md). The rules are in
      // apps/web/lint/xss-plugin.ts, because Oxlint's built-in ones cannot say what to write instead.
      // Turning one off takes a disable comment with a reason, and a blanket disable is not allowed.
      {
        files: ["apps/web/src/**"],
        jsPlugins: [{ name: "web-xss", specifier: "./apps/web/lint/xss-plugin.ts" }],
        plugins: ["unicorn"],
        rules: {
          "web-xss/no-html-injection": "error",
          "web-xss/no-javascript-url": "error",
          "web-xss/no-dynamic-code": "error",
          "web-xss/require-disable-reason": "error",
          "unicorn/no-abusive-eslint-disable": "error",
          // web-xss/no-dynamic-code reports eval with a message that says what to write instead.
          "no-eval": "off",
        },
      },
    ],
  },
});
